import{_ as r,a as d,b as i,c as o,d as l}from"./chunks/radiolink_power_modules.Dkh3Z33c.js";import{_ as n,C as h,c as s,o as p,j as e,G as c,al as u,a as m}from"./chunks/framework.CT7RwC5a.js";const y=JSON.parse('{"title":"RadiolinkPIX6 Flight Controller","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/radiolink_pix6.md","filePath":"en/flight_controller/radiolink_pix6.md"}'),b={name:"en/flight_controller/radiolink_pix6.md"};function f(g,t,P,S,C,V){const a=h("Badge");return p(),s("div",null,[t[0]||(t[0]=e("h1",{id:"radiolinkpix6-flight-controller",tabindex:"-1"},[m("RadiolinkPIX6 Flight Controller "),e("a",{class:"header-anchor",href:"#radiolinkpix6-flight-controller","aria-label":'Permalink to "RadiolinkPIX6 Flight Controller"'},"​")],-1)),c(a,{type:"tip",text:"main (planned for: PX4 v1.17)"}),t[1]||(t[1]=u('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://radiolink.com.cn/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The autopilot is recommended for commercial systems integration, but is also suitable for academic research and any other use.</p><p><img src="http://www.radiolink.com.cn/firmware/wiki/RadiolinkPIX6/RadiolinkPIX6.png" alt="RadiolinkPIX6"></p><p>The Radiolink PIX6 is a high-performance flight controller. Featuring STM32F7 CPU, vibration isolation of IMUs, redundant IMUs, integrated OSD chip, IMU heating, and DShot.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported.html">manufacturer supported</a>.</p></div><h2 id="quick-summary" tabindex="-1">Quick Summary <a class="header-anchor" href="#quick-summary" aria-label="Permalink to &quot;Quick Summary&quot;">​</a></h2><ul><li>Processor <ul><li>32-bit ARM Cortex M7 core with DPFPU - STM32F765VIT6</li><li>216 MHz/512 KB RAM/2 MB Flash</li><li>32-bit IOMCU co-processor - STM32F100</li><li>32KB FRAM - FM25V02A</li><li>AT7456E OSD</li></ul></li><li>Sensors <ul><li>Bosh BMI088 IMU (accel, gyro)</li><li>InvenSense ICM-42688 IMU (accel, gyro)</li><li>SPA06 barometer</li><li>IST8310 magnetometer</li></ul></li><li>Power <ul><li>SMBUS/I2C Power Module Inputs (I2C)</li><li>voltage and current monitor inputs (Analog)</li></ul></li><li>Interfaces <ul><li>16 PWM Outputs with independent power rail for external power source</li><li>5x UART serial ports, 2 with HW flow control</li><li>Camera Input and Video Output</li><li>PPM/SBUS input, DSM/SBUS input</li><li>RSSI (PWM or voltage) input</li><li>I2C, SPI, 2x CAN, USB</li><li>3.3V and 6.6V ADC inputs</li><li>Buzzer and Safety Switch</li><li>microSD card</li></ul></li><li>Weight and Dimensions: <ul><li>Weight 80g</li><li>Size 94mm x 51.5mm x 14.5mm</li></ul></li></ul><h2 id="where-to-buy" tabindex="-1">Where to Buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to Buy&quot;">​</a></h2><p><a href="https://www.radiolink.com.cn/pix6_where_to_buy" target="_blank" rel="noreferrer">Radiolink Amazon</a>（International users）</p><p><a href="https://item.taobao.com/item.htm?spm=a21dvs.23580594.0.0.1d292c1bNMdSqV&amp;ft=t&amp;id=815993357068&amp;skuId=5515756705284" target="_blank" rel="noreferrer">Radiolink Taobao</a>（China Mainland user）</p><h2 id="connector-assignments" tabindex="-1">Connector assignments <a class="header-anchor" href="#connector-assignments" aria-label="Permalink to &quot;Connector assignments&quot;">​</a></h2><h3 id="top-view" tabindex="-1">Top View <a class="header-anchor" href="#top-view" aria-label="Permalink to &quot;Top View&quot;">​</a></h3><p><img src="'+r+'" alt="Pix6 top view"></p><h3 id="left-view" tabindex="-1">Left View <a class="header-anchor" href="#left-view" aria-label="Permalink to &quot;Left View&quot;">​</a></h3><p><img src="'+d+'" alt="Pix6 left view"></p><h3 id="right-view" tabindex="-1">Right View <a class="header-anchor" href="#right-view" aria-label="Permalink to &quot;Right View&quot;">​</a></h3><p><img src="'+i+'" alt="Pix6 right view"></p><h3 id="rear-view" tabindex="-1">Rear View <a class="header-anchor" href="#rear-view" aria-label="Permalink to &quot;Rear View&quot;">​</a></h3><p><img src="'+o+'" alt="Pix6 rear view"></p><h2 id="pinouts" tabindex="-1">Pinouts <a class="header-anchor" href="#pinouts" aria-label="Permalink to &quot;Pinouts&quot;">​</a></h2><p>Unless noted otherwise all connectors are JST GH.</p><h3 id="telem1-telem2-ports" tabindex="-1">TELEM1, TELEM2 ports <a class="header-anchor" href="#telem1-telem2-ports" aria-label="Permalink to &quot;TELEM1, TELEM2 ports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>TX(OUT)</td><td>+3.3V</td></tr><tr><td>3</td><td>RX(IN)</td><td>+3.3V</td></tr><tr><td>4</td><td>CTS</td><td>+3.3V</td></tr><tr><td>5</td><td>RTS</td><td>+3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="osd" tabindex="-1">OSD <a class="header-anchor" href="#osd" aria-label="Permalink to &quot;OSD&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>GND</td><td>GND</td></tr><tr><td>2</td><td>VOUT</td><td>+3.3V</td></tr><tr><td>3</td><td>VCC</td><td>+5V</td></tr><tr><td>4</td><td>GND</td><td>GND</td></tr><tr><td>5</td><td>VCC</td><td>+5V</td></tr><tr><td>6</td><td>VIN</td><td>+3.3V</td></tr></tbody></table><h3 id="i2c-port" tabindex="-1">I2C port <a class="header-anchor" href="#i2c-port" aria-label="Permalink to &quot;I2C port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>SCL</td><td>+3.3V (pullups)</td></tr><tr><td>3</td><td>SDA</td><td>+3.3V (pullups)</td></tr><tr><td>4</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="can1-can2-ports" tabindex="-1">CAN1, CAN2 ports <a class="header-anchor" href="#can1-can2-ports" aria-label="Permalink to &quot;CAN1, CAN2 ports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>CAN_H</td><td>+12V</td></tr><tr><td>3</td><td>CAN_L</td><td>+12V</td></tr><tr><td>4</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="gps1-port" tabindex="-1">GPS1 port <a class="header-anchor" href="#gps1-port" aria-label="Permalink to &quot;GPS1 port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>TX(OUT)</td><td>+3.3V</td></tr><tr><td>3</td><td>RX(IN)</td><td>+3.3V</td></tr><tr><td>4</td><td>SCL</td><td>+3.3V</td></tr><tr><td>5</td><td>SDA</td><td>+3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="gps2-port" tabindex="-1">GPS2 Port <a class="header-anchor" href="#gps2-port" aria-label="Permalink to &quot;GPS2 Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>TX(OUT)</td><td>+3.3V</td></tr><tr><td>3</td><td>RX(IN)</td><td>+3.3V</td></tr><tr><td>4</td><td>SCL</td><td>+3.3V</td></tr><tr><td>5</td><td>SDA</td><td>+3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="spi" tabindex="-1">SPI <a class="header-anchor" href="#spi" aria-label="Permalink to &quot;SPI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>SPI_SCK</td><td>+3.3V</td></tr><tr><td>3</td><td>SPI_MISO</td><td>+3.3V</td></tr><tr><td>4</td><td>SPI_MOSI</td><td>+3.3V</td></tr><tr><td>5</td><td>!SPI_NSS1</td><td>+3.3V</td></tr><tr><td>6</td><td>!SPI_NSS2</td><td>+3.3V</td></tr><tr><td>7</td><td>DRDY</td><td>+3.3V</td></tr><tr><td>8</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="power1-hy2-0-6p" tabindex="-1">POWER1 (HY2.0-6P) <a class="header-anchor" href="#power1-hy2-0-6p" aria-label="Permalink to &quot;POWER1 (HY2.0-6P)&quot;">​</a></h3><p>Port for analog power monitors.</p><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>VCC</td><td>+5V</td></tr><tr><td>3</td><td>CURRENT</td><td>up to +3.3V</td></tr><tr><td>4</td><td>VOLTAGE</td><td>up to +3.3V</td></tr><tr><td>5</td><td>GND</td><td>GND</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="power2-hy2-0-6p" tabindex="-1">POWER2 (HY2.0-6P) <a class="header-anchor" href="#power2-hy2-0-6p" aria-label="Permalink to &quot;POWER2 (HY2.0-6P)&quot;">​</a></h3><p>Port for digital (I2C) power monitor.</p><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>VCC</td><td>+5V</td></tr><tr><td>3</td><td>SCL</td><td>+3.3V</td></tr><tr><td>4</td><td>SDA</td><td>+3.3V</td></tr><tr><td>5</td><td>GND</td><td>GND</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="adc-3-3v" tabindex="-1">ADC 3.3V <a class="header-anchor" href="#adc-3-3v" aria-label="Permalink to &quot;ADC 3.3V&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>ADC IN1</td><td>up to +3.3V</td></tr><tr><td>3</td><td>GND</td><td>GND</td></tr><tr><td>4</td><td>ADC IN2</td><td>up to +3.3v</td></tr><tr><td>5</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="adc-6-6v" tabindex="-1">ADC 6.6V <a class="header-anchor" href="#adc-6-6v" aria-label="Permalink to &quot;ADC 6.6V&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>ADC IN</td><td>up to 6.6V</td></tr><tr><td>3</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="usb-remote-port" tabindex="-1">USB remote port <a class="header-anchor" href="#usb-remote-port" aria-label="Permalink to &quot;USB remote port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>USB VDD</td><td>+5V</td></tr><tr><td>2</td><td>DM</td><td>+3.3V</td></tr><tr><td>3</td><td>DP</td><td>+3.3V</td></tr><tr><td>4</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="switch" tabindex="-1">SWITCH <a class="header-anchor" href="#switch" aria-label="Permalink to &quot;SWITCH&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+3.3V</td></tr><tr><td>2</td><td>!IO_LED_SAFETY</td><td>GND</td></tr><tr><td>3</td><td>SAFETY</td><td>GND</td></tr></tbody></table><h3 id="buzzer-port" tabindex="-1">Buzzer port <a class="header-anchor" href="#buzzer-port" aria-label="Permalink to &quot;Buzzer port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>BUZZER-</td><td>+5V</td></tr></tbody></table><h3 id="spektrum-dsm-port-ph1-25-3p" tabindex="-1">Spektrum/DSM Port (PH1.25-3P) <a class="header-anchor" href="#spektrum-dsm-port-ph1-25-3p" aria-label="Permalink to &quot;Spektrum/DSM Port (PH1.25-3P)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+3.3V</td></tr><tr><td>2</td><td>GND</td><td>GND</td></tr><tr><td>3</td><td>Signal</td><td>+3.3V</td></tr></tbody></table><h3 id="debug-port-sh1-0-8p" tabindex="-1">Debug port (SH1.0-8P) <a class="header-anchor" href="#debug-port-sh1-0-8p" aria-label="Permalink to &quot;Debug port (SH1.0-8P)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1</td><td>VCC</td><td>+5V</td></tr><tr><td>2</td><td>FMU_SWCLK</td><td>+3.3V</td></tr><tr><td>3</td><td>FMU_SWDIO</td><td>+3.3V</td></tr><tr><td>4</td><td>TX(UART7)</td><td>+3.3V</td></tr><tr><td>5</td><td>RX(UART7)</td><td>+3.3V</td></tr><tr><td>6</td><td>IO_SWCLK</td><td>+3.3V</td></tr><tr><td>7</td><td>IO_SWDIO</td><td>+3.3V</td></tr><tr><td>8</td><td>GND</td><td>GND</td></tr></tbody></table><h2 id="building-firmware" tabindex="-1">Building Firmware <a class="header-anchor" href="#building-firmware" aria-label="Permalink to &quot;Building Firmware&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4.html">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> radiolink_PIX6_default</span></span></code></pre></div><h2 id="installing-px4-firmware" tabindex="-1">Installing PX4 Firmware <a class="header-anchor" href="#installing-px4-firmware" aria-label="Permalink to &quot;Installing PX4 Firmware&quot;">​</a></h2><p>The firmware can be installed in any of the normal ways:</p><ul><li><p>Build and upload the source</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> radiolink_PIX6_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><a href="./../config/firmware.html">Load the firmware</a> using <em>QGroundControl</em>. You can use either pre-built firmware or your own custom firmware.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>At time of writing the only pre-built software is <code>PX4 main</code> (see <a href="./../config/firmware.html#installing-px4-main-beta-or-custom-firmware">Installing PX4 Main, Beta or Custom Firmware</a>). Release builds will be supported for PX4 v1.17 and later.</p></div></li></ul><h2 id="px4-configuration" tabindex="-1">PX4 Configuration <a class="header-anchor" href="#px4-configuration" aria-label="Permalink to &quot;PX4 Configuration&quot;">​</a></h2><p>In addition to the <a href="./../config/">basic configuration</a>, the following parameters are important:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Setting</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference.html#SYS_HAS_MAG">SYS_HAS_MAG</a></td><td>This should be disabled since the board does not have an internal mag. You can enable it if you attach an external mag.</td></tr></tbody></table><h3 id="powering-the-pix6" tabindex="-1">Powering the PIX6 <a class="header-anchor" href="#powering-the-pix6" aria-label="Permalink to &quot;Powering the PIX6&quot;">​</a></h3><p>The PIX6 has 2 dedicated power monitor ports, each with a 6 pin connector. One is the Analog power monitor (<code>POWER1</code>), and the others is the I2C power monitor (<code>POWER2</code>).</p><p>The power module that comes with the flight controller with a wide voltage input range of 2-12S (7.4-50.4V), a maximum detection current of 90A (single ESC maximum detection current is 22.5A), a BEC output voltage of 5.3±0.2V, and a BEC output current of 2A.</p><p><img src="'+l+'" alt="Radiolink power modules MODULES"></p><p>The PIX6 also supports power modules from other manufacturers, such as <a href="./../power_module/holybro_pm02d.html">holybro_pm02d</a>.</p><h2 id="recommended-accessories" tabindex="-1">Recommended Accessories <a class="header-anchor" href="#recommended-accessories" aria-label="Permalink to &quot;Recommended Accessories&quot;">​</a></h2><h3 id="gps-modules" tabindex="-1">GPS Modules <a class="header-anchor" href="#gps-modules" aria-label="Permalink to &quot;GPS Modules&quot;">​</a></h3><p>Radiolink manufactures a variety of high-performance GPS，Dual Anti-interference Technology Worry-free of UAV High-power Image Transmission, High-Voltage Lines, or Other Strong Signal Interference.</p><p>The PIX6 has 2 dedicated GPS ports, <code>GPS1</code> and <code>GPS2</code>, each with a 6 pin connector.</p><p>Recommended modules include:</p><ul><li><a href="https://radiolink.com.cn/se100" target="_blank" rel="noreferrer">Radiolink SE100</a></li><li><a href="https://radiolink.com.cn/ts100v2" target="_blank" rel="noreferrer">Radiolink TS100</a></li><li><a href="https://radiolink.com.cn/rtk_f9p" target="_blank" rel="noreferrer">Radiolink RTK F9P</a></li></ul><h2 id="serial-port-mapping" tabindex="-1">Serial Port Mapping <a class="header-anchor" href="#serial-port-mapping" aria-label="Permalink to &quot;Serial Port Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Device</th><th>Port</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>GPS1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (flow control)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (flow control)</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>GPS2</td></tr><tr><td>UART7</td><td>/dev/ttyS4</td><td>Debug Console</td></tr><tr><td>UART8</td><td>/dev/ttyS5</td><td>PX4IO</td></tr></tbody></table><h2 id="analog-inputs" tabindex="-1">Analog inputs <a class="header-anchor" href="#analog-inputs" aria-label="Permalink to &quot;Analog inputs&quot;">​</a></h2><p>The Radiolink PIX6 has 3 analog inputs, one 6V tolerant and two 3.3V tolerant.</p><ul><li>ADC Pin12 -&gt; ADC 6.6V Sense</li><li>ADC Pin4 -&gt; ADC IN1 3.3V Sense</li><li>ADC Pin13 -&gt; ADC IN2 3.3V Sense</li></ul><h2 id="radio-control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio-control" aria-label="Permalink to &quot;Radio Control&quot;">​</a></h2><p>A <a href="./../getting_started/rc_transmitter_receiver.html">Radio Control (RC)</a> system is required if you want to <em>manually</em> control your vehicle (PX4 does not require a radio system for autonomous flight modes).</p><p>You will need to <a href="./../getting_started/rc_transmitter_receiver.html">select a compatible transmitter/receiver</a> and then <em>bind</em> them so that they communicate (read the instructions that come with your specific transmitter/receiver).</p><ul><li>Spektrum/DSM receivers connect to the <strong>DSM/SBUS RC</strong> input.</li><li>PPM or SBUS receivers connect to the <strong>RC IN</strong> input port.</li><li>CRSF receiver must be wired to a spare port (UART) on the Flight Controller. Then you can bind the transmitter and receiver together.</li></ul><h4 id="crsf-parameter-configuration" tabindex="-1">CRSF Parameter Configuration <a class="header-anchor" href="#crsf-parameter-configuration" aria-label="Permalink to &quot;CRSF Parameter Configuration&quot;">​</a></h4><p><a href="./../advanced_config/parameters.html">Find and set</a> the following parameters:</p><ol><li><p>Set <a href="./../advanced_config/parameter_reference.html#RC_CRSF_PRT_CFG">RC_CRSF_PRT_CFG</a> to the port that is connected to the CRSF receiver (such as <code>TELEM1</code>).</p><p>This <a href="./../peripherals/serial_configuration.html">configures the serial port</a> to use the CRSF protocol. Note that some serial ports may already have a <a href="./../peripherals/serial_configuration.html#default-serial-port-configuration">default serial port mapping</a> or <a href="./../peripherals/mavlink_peripherals.html#default-mavlink-ports">default MAVLink serial port mapping</a> that you will have to un-map before you can assign the port to CRSF. For example, if you want to use <code>TELEM1</code> or <code>TELEM2</code> you first need to modify <a href="./../advanced_config/parameter_reference.html#MAV_0_CONFIG">MAV_0_CONFIG</a> or <a href="./../advanced_config/parameter_reference.html#MAV_1_CONFIG">MAV_1_CONFIG</a> to stop setting those ports.</p><p>There is no need to set the baud rate for the port, as this is configured by the driver.</p></li><li><p>Enable <a href="./../advanced_config/parameter_reference.html#RC_CRSF_TEL_EN">RC_CRSF_TEL_EN</a> to activate Crossfire telemetry.</p></li></ol><p>For more information about selecting a radio system, receiver compatibility, and binding your transmitter/receiver pair, see: <a href="./../getting_started/rc_transmitter_receiver.html">Remote Control Transmitters &amp; Receivers</a>.</p>',88))])}const w=n(b,[["render",f]]);export{y as __pageData,w as default};
